444	// Updates only the given keys in place, preserving comments/ordering/everything
445	// else — unlike scaffold(), which is only used for brand-new files. With
446	// fillOnly, an already-non-blank existing value is left alone instead of being
447	// overwritten — used for one-off migration from a pre-existing .env, where we
448	// never want to silently clobber something the dev already set by hand.
449	function upsertKeys(filePath, updates, canWrite, fillOnly = false) {
450	  const lines = parseEnvLines(fs.readFileSync(filePath, 'utf8'));
451	  const changes = [];
452	  for (const [key, value] of Object.entries(updates)) {
453	    if (!value) continue;
454	    const existing = lines.find((line) => line.type === 'var' && line.key === key);
455	    if (!existing) {
456	      lines.push({ type: 'var', key, value });
457	      changes.push({ action: 'add', key });
458	    } else if (!existing.value.trim()) {
459	      existing.value = value;
460	      changes.push({ action: 'fill', key });
461	    } else if (!fillOnly && existing.value.trim() !== value) {
462	      existing.value = value;
463	      changes.push({ action: 'update', key });
464	    }
465	  }
466	  if (changes.length && canWrite) {
467	    fs.writeFileSync(filePath, serializeEnvLines(lines));
468	  }
469	  return changes;
